package br.edu.vendas.converter;
import br.edu.vendas.model.Marca; import br.edu.vendas.service.MarcaService; import jakarta.faces.component.UIComponent; import jakarta.faces.context.FacesContext; import jakarta.faces.convert.Converter; import jakarta.faces.convert.FacesConverter; import jakarta.inject.Inject;
@FacesConverter(value="marcaConverter",managed=true) public class MarcaConverter implements Converter<Marca>{ @Inject MarcaService service; public Marca getAsObject(FacesContext c,UIComponent u,String v){if(v==null||v.isBlank())return null;return service.listar().stream().filter(x->String.valueOf(x.getId()).equals(v)).findFirst().orElse(null);} public String getAsString(FacesContext c,UIComponent u,Marca v){return v==null||v.getId()==null?"":v.getId().toString();}}
